head.script:
scwin.screenId = "jldfil35706";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.sub_printDate_Y = undefined;
scwin.sub_printDate_M = undefined;
scwin.sub_printDate_D = undefined;

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (method 확보)
        scwin.init_nowVars(); // 2) 오늘 일자(today) 미수신 시 서버 일자 충전
        scwin.init_fillGen(); // 3) 입금내역 제너레이터(c_foreach_77) 채움
        scwin.init_rowCopy(); // 4) 페이지 요약 문구(전체 건수/페이지) 표시
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35706.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값(today)을 dma_pageContext 에 충전한다 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
 * @returns {void}
 * @hidden N
 * @example scwin.init_nowVars();
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_fillGen
 * @description 입금내역 제너레이터(c_foreach_77)를 dlt_result 데이터로 채운다 — 진입점(onpageload)에서 순차 실행하며, 이미 채워진 제너레이터는 건너뛴다(멱등). 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_fillGen();
 */
scwin.init_fillGen = function () {
    const genFills = [{
        genId: "c_foreach_77",
        entity: "dlt_result",
        countIds: [],
        cells: [
            { childId: "ipt_checkType", fn: function (v, idx) { return String(v("seq")); } },
            { childId: "__rc1", fn: function (v, idx) { return String(v("payDd")); } },
            { childId: "__rc2", fn: function (v, idx) { return String(v("lstPayAmt")); } },
            { childId: "__rc3", fn: function (v, idx) { return String(v("lstFeeAnulfeeTpCdnm")); } }
        ]
    }];
    for (let g = 0; g < genFills.length; g++) {
        const f = genFills[g];
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { continue; }
        const n = ds.getTotalRow();
        if (!n) { continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        if (gen.getLength && gen.getLength() > 0) { continue; }
        let rowIdx = 0;
        const cellOf = function (col) {
            const v = ds.getCellData(rowIdx, col);
            return (v === undefined || v === null) ? '' : v;
        };
        for (let i = 0; i < n; i++) {
            rowIdx = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cellOf, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
        }
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description 페이지 요약 문구(__rb0)에 dma_page 의 전체 건수·현재/끝 페이지를 조립해 표시한다 — 진입점에서 1회, 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_rowCopy();
 */
scwin.init_rowCopy = function () {
    const rowCopies = [{
        childId: "__rb0",
        fn: function () {
            const readPage = function (key) {
                return String($c.data.readValue("dma_page", key, { silent: true }));
            };
            return "전체 " + readPage("total") + "건 (" + readPage("currentPage") + "/" + readPage("endListPage") + " 페이지) ";
        }
    }];
    $c.data.copyRows(rowCopies);
};

/**
 * @method
 * @name initPageIndex
 * @description 조회 요청 전문(dma_goPrintReq)의 pageIndex 를 1페이지로 초기화한다(페이지 크기 변경 시 재조회 선행 단계).
 * @returns {void}
 * @hidden N
 * @example scwin.initPageIndex();
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_goPrintReq').set('pageIndex', "1");
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫).
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name cal_startDate_onblur
 * @description 입금일 시작일 달력 blur — 입력한 일자의 형식을 검증한다($c.cm.fn_CheckDate).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onblur 바인딩으로 자동 호출)
 */
scwin.cal_startDate_onblur = function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.cm.fn_CheckDate(selfEl);
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldfil35706.cal_startDate_onblur' });
    }
};

/**
 * @method
 * @name cal_endDate_onblur
 * @description 입금일 종료일 달력 blur — 입력한 일자의 형식을 검증한다($c.cm.fn_CheckDate).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onblur 바인딩으로 자동 호출)
 */
scwin.cal_endDate_onblur = function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.cm.fn_CheckDate(selfEl);
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldfil35706.cal_endDate_onblur' });
    }
};

/**
 * @method
 * @name rd_period_onclick
 * @description 조회기간 라디오 클릭 — 기간 유형('7D')으로 시작/종료일을 재설정한다(scwin.changePeriod).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.rd_period_onclick = function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changePeriod('7D', selfEl);
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldfil35706.rd_period_onclick' });
    }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description [검색] 버튼 클릭 — 입금일 기간으로 상장수수료 영수증 목록을 조회한다(scwin.fn_searchList).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_searchList_onclick = async function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.fn_searchList();
    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldfil35706.btn_searchList_onclick' });
    }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description 페이지당 건수 셀렉트 변경 — pageIndex 를 1로 초기화한 뒤 목록을 재조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onchange 바인딩으로 자동 호출)
 */
scwin.slc_pageSize_onchange = async function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.initPageIndex();
        await scwin.fn_searchList();
    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldfil35706.slc_pageSize_onchange' });
    }
};

/**
 * @method
 * @name btn_printReceipt_onclick
 * @description [인쇄] 버튼 클릭 — 체크한 영수증발급 대상 1건을 확인해 영수증을 인쇄한다(scwin.fn_printReceipt).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_printReceipt_onclick = async function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.fn_printReceipt();
    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldfil35706.btn_printReceipt_onclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name tx_fn_goPrint
 * @description 상장수수료 영수증 리포트 파일을 다운로드한다(공용 $c.data.downFile, dma_goPrintReq 전문 사용). 실패 시 오류를 무통지 수집하고 null 을 반환한다.
 * @returns {Object} 다운로드 결과 객체(실패 시 null)
 * @hidden N
 * @example await scwin.tx_fn_goPrint();
 */
scwin.tx_fn_goPrint = async function () {
    try {
        const printReq = $c.util.getComponent("dma_goPrintReq");
        return await $c.data.downFile("/common/newPrint.do", "", (printReq ? printReq.getJSON() : {}));
    } catch (_e) {
        await $c.exception.handleError(_e, { notify: 'none', context: '다운로드' });
        return null;
    }
};

/**
 * @method
 * @name tx_fn_goTab2
 * @description 영수증출력 탭 초기 목록을 서버에 조회해 dlt_result 에 적재한다(listFee.do, dma_goTab2Req 전문). 응답 실패 시 서버 메시지를 알린다.
 * @returns {Object} executeDynamic 응답 객체(resObj, 통신 오류 시 null)
 * @hidden N
 * @example const res = await scwin.tx_fn_goTab2();
 */
scwin.tx_fn_goTab2 = async function () {
    const sbmOptions = {
        id: "tx_fn_goTab2",
        method: "post",
        action: "listFee.do",
        ref: "dma_goTab2Req",
        target: "dlt_result=body",
        isProcessMsg: false
    };
    let res = null;
    try {
        res = await $c.sbm.executeDynamic(sbmOptions);
    } catch (_e) {
        await $c.exception.handleError(_e, { notify: 'none', context: "jldfil35706.tx_fn_goTab2" });
        return null;
    }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
        return res;
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name fn_searchList
 * @description 입금일 기간을 검증한 뒤(시작일 > 종료일이면 중단) 조회 전문(dma_goPrintReq, method=searchListFeeReceipt)을 listFee.do 에 POST 제출한다($c.win.openFormSubmit — as-is listFeeReceiptForm.submit 의 JSP 페이지 전환 의미 보존).
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_searchList();
 */
scwin.fn_searchList = async function () {
    if ($c.util.getComponent('cal_startDate').getValue() > $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    const printReq = $c.util.getComponent('dma_goPrintReq');
    printReq.set('method', "searchListFeeReceipt");
    // form 제출 재설계 — as-is: listFeeReceiptForm.submit()(action=listFee.do, 폼 필드 전부 dma_goPrintReq ref 바인딩)
    $c.win.openFormSubmit('listFee.do', printReq.getJSON());
};


/**
 * @method
 * @name fn_printReceipt
 * @description 목록(dlt_result)에서 체크(seq)된 영수증발급 대상을 집계해 정확히 1건이면 인쇄(fn_goPrint)를 호출하고, 아니면 1건 체크 안내를 띄운다.
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_printReceipt();
 */
scwin.fn_printReceipt = async function () {
    const dltResult = $c.util.getComponent('dlt_result');
    let cnt = 0;
    let seq = 0;
    let isurCd = "";
    let rcvDd = "";
    if ((dltResult.getTotalRow() > 0)) {
        if (dltResult.getTotalRow()) {
            for (let i = 0; i < dltResult.getTotalRow(); i++) {
                if ((['true', 'Y', '1'].indexOf(String(dltResult.getCellData(i, 'seq'))) >= 0)) {
                    cnt = cnt + 1;
                    seq = dltResult.getCellData(i, 'seq');
                    isurCd = dltResult.getCellData(i, 'isurCd');
                    rcvDd = dltResult.getCellData(i, 'rcvDd');
                }
            }
        } else {
            if ((dltResult.getTotalRow() > 0).checked) {
                cnt = cnt + 1;
                seq = dltResult.getCellData(0, 'seq');
                isurCd = $c.util.getComponent('dma_goPrintReq').get('isurCd');
                rcvDd = $c.util.getComponent('dma_goPrintReq').get('rcvDd');
            }
        }
    }
    if (cnt === 1) {
        scwin.fn_goPrint(seq, isurCd, rcvDd);
    } else {
        await $c.win.alert("영수증발급 대상을 1개 체크후 인쇄를 누르세요.");
        return;
    }
};


/**
 * @method
 * @name fn_goPrint
 * @description 선택 건의 영수증 리포트 데이터를 동기 ajax 로 조회해 dma_goPrintReq 전문(회사명·입금일·입금액 1~9·수수료구분·템플릿코드·출력일)을 채운 뒤 리포트 다운로드(tx_fn_goPrint)를 호출한다. 조회 실패 시 장애 알림을 띄운다.
 * @param {String} seq 영수증 일련번호
 * @param {String} isurCd 발행사 고유코드
 * @param {String} rcvDd 입금일
 * @returns {void}
 * @hidden N
 * @example scwin.fn_goPrint(seq, isurCd, rcvDd);
 */
scwin.fn_goPrint = function (seq, isurCd, rcvDd) {
    const rexName = "RLDFIL00030";
    const dataLocation = "/outer/reportPrint.do?ipt_method_2=searchListFeeNewReport&isurCd=" + isurCd + "&rcvDd=" + rcvDd + "&seq=" + seq;
    $.ajax({
        type: "POST",
        async: false,
        url: dataLocation,
        data: {},
        success: async function (data) {
            const result = $.parseJSON(data);
            // form 제출 재설계 — as-is newReportForm 제출(→ /common/newPrint.do)은 tx_fn_goPrint 의
            // $c.data.downFile 로 파일 다운로드 의미가 이미 보존돼 폼 기계부는 제거(새 창 target 부재 실측).
            const printReq = $c.util.getComponent('dma_goPrintReq');
            printReq.set('ncomNm', result.comNm);
            printReq.set('npayDd', result.payDd);
            printReq.set('nlstPayAmt', result.lstPayAmt);
            printReq.set('nlstPayAmt1', '');
            printReq.set('nlstPayAmt2', '');
            printReq.set('nlstPayAmt3', '');
            printReq.set('nlstPayAmt4', '');
            printReq.set('nlstPayAmt5', '');
            printReq.set('nlstPayAmt6', '');
            printReq.set('nlstPayAmt7', '');
            printReq.set('nlstPayAmt8', '');
            printReq.set('nlstPayAmt9', '');
            if (typeof result.lstPayAmt1 !== 'undefined') {
                printReq.set('nlstPayAmt1', result.lstPayAmt1);
            }
            if (typeof result.lstPayAmt2 !== 'undefined') {
                printReq.set('nlstPayAmt2', result.lstPayAmt2);
            }
            if (typeof result.lstPayAmt3 !== 'undefined') {
                printReq.set('nlstPayAmt3', result.lstPayAmt3);
            }
            if (typeof result.lstPayAmt4 !== 'undefined') {
                printReq.set('nlstPayAmt4', result.lstPayAmt4);
            }
            if (typeof result.lstPayAmt5 !== 'undefined') {
                printReq.set('nlstPayAmt5', result.lstPayAmt5);
            }
            if (typeof result.lstPayAmt6 !== 'undefined') {
                printReq.set('nlstPayAmt6', result.lstPayAmt6);
            }
            if (typeof result.lstPayAmt7 !== 'undefined') {
                printReq.set('nlstPayAmt7', result.lstPayAmt7);
            }
            if (typeof result.lstPayAmt8 !== 'undefined') {
                printReq.set('nlstPayAmt8', result.lstPayAmt8);
            }
            if (typeof result.lstPayAmt9 !== 'undefined') {
                printReq.set('nlstPayAmt9', result.lstPayAmt9);
            }
            printReq.set('nlstFeeAnulfeeTpCdnm', result.lstFeeAnulfeeTpCdnm);
            printReq.set('nTempleteCd', rexName);
            if (result.today) {
                const sub_printDate = result.today;
                scwin.sub_printDate_Y = sub_printDate.substring(0, 4);
                scwin.sub_printDate_M = sub_printDate.substring(4, 6);
                scwin.sub_printDate_D = sub_printDate.substring(6, 8);
                printReq.set('ntoDay', scwin.sub_printDate_Y + "." + scwin.sub_printDate_M + "." + scwin.sub_printDate_D);
            } else {
                printReq.set('ntoDay', result.today);
            }
            await scwin.tx_fn_goPrint();
        },
        error: async function (request, status, error) {
            await $c.win.alert("장애발생.");
            return;
        },
        complete: function () {

        }
    });
};


/**
 * @method
 * @name changePeriod
 * @description 기간 유형('7D'/'1M'/'1Y'/'2Y')에 따라 시작/종료일 달력을 오늘 기준 상대 기간으로 재설정한다(fn_setDate/fn_setMonth/fn_setFullYear 위임).
 * @param {String} type 기간 유형 코드('7D'|'1M'|'1Y'|'2Y')
 * @param {Object} obj 이벤트 발생 컴포넌트(as-is 시그니처 보존용, 미사용)
 * @returns {void}
 * @hidden N
 * @example scwin.changePeriod('7D', selfEl);
 */
scwin.changePeriod = function (type, obj) {
    const startDate = ($c.util.getComponent('cal_startDate') || $c.util.getComponent('ipt_startDate') || $c.util.getComponent('startDate'));
    const endDate = ($c.util.getComponent('cal_endDate') || $c.util.getComponent('ipt_endDate') || $c.util.getComponent('endDate'));
    const ie = null;
    switch (type) {
        case '7D':
            scwin.fn_setDate(7, startDate, endDate, ie);
            break;
        case '1M':
            scwin.fn_setMonth(1, startDate, endDate, ie);
            break;
        case '1Y':
            scwin.fn_setFullYear(1, startDate, endDate, ie);
            break;
        case '2Y':
            scwin.fn_setFullYear(2, startDate, endDate, ie);
            break;
    }
};


/**
 * @method
 * @name fn_setDate
 * @description 오늘부터 pNewDd 일 전 ~ 오늘 구간을 yyyyMMdd 로 조립해 cal_startDate/cal_endDate 에 설정한다(월·일 2자리 0 패딩).
 * @param {Number} pNewDd 시작일을 오늘로부터 며칠 전으로 둘지(일수)
 * @param {Object} startDate 시작일 컴포넌트(as-is 시그니처 보존용, 미사용)
 * @param {Object} endDate 종료일 컴포넌트(as-is 시그니처 보존용, 미사용)
 * @param {Object} ie 브라우저 구분 플래그(as-is 시그니처 보존용, 미사용)
 * @returns {void}
 * @hidden N
 * @example scwin.fn_setDate(7, startDate, endDate, null);
 */
scwin.fn_setDate = function (pNewDd, startDate, endDate, ie) {
    const vDate = new Date();
    const vDate2 = new Date();
    let vMon2;
    let vMon;
    let vDay2;
    let vDay;
    vDate.setDate(vDate.getDate());
    vDate2.setDate(vDate.getDate() - pNewDd);
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};


