/**
 * @method
 * @name fn_setFullYear
 * @description 오늘부터 pNewyear 년 전 ~ 오늘 구간을 yyyyMMdd 로 조립해 cal_startDate/cal_endDate 에 설정한다(월·일 2자리 0 패딩, ie 분기는 as-is 잔재로 양쪽 동일 로직).
 * @param {Number} pNewyear 시작일을 오늘로부터 몇 년 전으로 둘지(연수)
 * @param {Object} startDate 시작일 컴포넌트(as-is 시그니처 보존용, 미사용)
 * @param {Object} endDate 종료일 컴포넌트(as-is 시그니처 보존용, 미사용)
 * @param {Object} ie 브라우저 구분 플래그(as-is 잔재 — 분기 양쪽이 동일 로직)
 * @returns {void}
 * @hidden N
 * @example scwin.fn_setFullYear(1, startDate, endDate, null);
 */
scwin.fn_setFullYear = function (pNewyear, startDate, endDate, ie) {
    const vDate = new Date();
    const vDate2 = new Date();
    let vMon2;
    let vMon;
    let vDay2;
    let vDay;
    if (!ie) {
        vDate.setFullYear(vDate.getFullYear());
        vDate2.setFullYear(vDate.getFullYear() - pNewyear);
    } else {
        vDate.setFullYear(vDate.getFullYear());
        vDate2.setFullYear(vDate.getFullYear() - pNewyear);
    }
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};


/**
 * @method
 * @name fn_goTab1
 * @description 상장수수료 계산 탭(jldfil35700)으로 이동한다(method=searchListFeeCalc 설정 후 화면 전환 — as-is listFeeReceiptForm 제출은 $c.win.moveUrl 화면 전환으로 재설계됨).
 * @returns {void}
 * @hidden N
 * @example scwin.fn_goTab1();
 */
scwin.fn_goTab1 = function () {
    $c.util.getComponent('dma_goPrintReq').set('method', 'searchListFeeCalc');
    $c.win.moveUrl("/jldfil35700/jldfil35700.xml", { "method": 'searchListFeeCalc' });
};


/**
 * @method
 * @name fn_goTab2
 * @description 영수증출력 탭 초기 조회를 수행한다(method=initListFeeReceipt 설정 후 tx_fn_goTab2 호출 — as-is listFeeReceiptForm 제출(listFee.do)은 executeDynamic 조회로 재설계됨).
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_goTab2();
 */
scwin.fn_goTab2 = async function () {
    $c.util.getComponent('dma_goPrintReq').set('method', 'initListFeeReceipt');
    await scwin.tx_fn_goTab2();
};


/**
 * @method
 * @name krxpage_pagenavigator_87_onclick
 * @description 페이지 내비게이터 클릭 — 선택한 페이지 번호를 pageIndex 에 반영한 뒤 목록을 재조회한다.
 * @param {Number} index 이동할 페이지 번호
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.krxpage_pagenavigator_87_onclick = function (index) {
    try {
        $c.util.getComponent('dma_goPrintReq').set('pageIndex', index);
    } catch (e) {
        $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_87.page' });
    }
    scwin.fn_searchList();
};
